43|// On a 1024x1024 matrix this strides by 8KB per access, blowing the L1
44|// cache on every load. This is the slow path callers complain about.
45|std::vector<double> Matrix::SumPerColumn() const {
46|    struct StridedIter {
47|        const double* p;
48|        std::ptrdiff_t stride;
49|        using iterator_category = std::random_access_iterator_tag;
50|        using value_type = double;
51|        using difference_type = std::ptrdiff_t;
52|        using pointer = const double*;
53|        using reference = double;
54|        double operator*() const { return *p; }
55|        StridedIter& operator++() { p += stride; return *this; }
56|        StridedIter operator++(int) { auto t = *this; ++(*this); return t; }
57|        StridedIter& operator--() { p -= stride; return *this; }
58|        StridedIter operator--(int) { auto t = *this; --(*this); return t; }
59|        StridedIter& operator+=(difference_type n) { p += n * stride; return *this; }
60|        StridedIter& operator-=(difference_type n) { p -= n * stride; return *this; }
61|        StridedIter operator+(difference_type n) const { auto t = *this; return t += n; }
62|        StridedIter operator-(difference_type n) const { auto t = *this; return t -= n; }
63|        difference_type operator-(const StridedIter& o) const { return (p - o.p) / stride; }
64|        double operator[](difference_type n) const { return p[n * stride]; }
65|        bool operator==(const StridedIter& o) const { return p == o.p; }
66|        bool operator!=(const StridedIter& o) const { return p != o.p; }
67|        bool operator<(const StridedIter& o) const { return p < o.p; }
68|        bool operator>(const StridedIter& o) const { return p > o.p; }
69|        bool operator<=(const StridedIter& o) const { return p <= o.p; }
70|        bool operator>=(const StridedIter& o) const { return p >= o.p; }
71|    };
